LOCAL = os.environ.get("LLM2NCM_LOCAL") == "1"
if LOCAL and os.environ.get("LLM2NCM_CONFIG"):
    CONFIG = json.loads(os.environ["LLM2NCM_CONFIG"])
ROOT = os.environ.get("LLM2NCM_ROOT", "/tmp/llm2ncm_local") if LOCAL else "/tmp"
OUT = f"{ROOT}/out" if LOCAL else "/kaggle/working"
SRC, DATA, WORK, RECIPES = f"{ROOT}/src", f"{ROOT}/msdata", f"{ROOT}/work", f"{ROOT}/recipes"
DEVICE = "cpu" if LOCAL else "cuda"
T0 = time.time()
BASE = CONFIG["base_model"]
TEXT = f"{ROOT}/" + BASE.split("/")[-1] + "-textonly"   # named so REPORT.md's header identifies the model
ENV = {**os.environ, "HF_HOME": os.environ.get("HF_HOME", "/tmp/hf"), "TOKENIZERS_PARALLELISM": "false", "HF_HUB_DISABLE_TELEMETRY": "1"}

os.makedirs(OUT, exist_ok=True)
_log = open(f"{OUT}/run.log", "a", buffering=1)
_lock = threading.Lock()
stages = {}


def log(*a):
    line = f"[{time.time() - T0:7.1f}s] " + " ".join(str(x) for x in a)
    with _lock:
        print(line, flush=True)
        _log.write(line + "\n")


def run(name, cmd, check=True):
    """Run cmd, stream its output to stdout and run.log, record duration/exit code in `stages`."""
    log(f"=== {name}: {' '.join(map(str, cmd))}")
    t = time.time()
    p = subprocess.Popen([str(c) for c in cmd], cwd=ROOT if LOCAL else "/tmp", env=ENV, stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT, text=True, bufsize=1, errors="replace")
    for line in p.stdout:
        sys.stdout.write(line)
        sys.stdout.flush()
        _log.write(line)
    rc = p.wait()
    stages[name] = {"exit": rc, "seconds": round(time.time() - t)}
    log(f"=== {name}: exit {rc} after {time.time() - t:.0f}s")
    if check and rc != 0:
        raise RuntimeError(f"stage '{name}' failed with exit code {rc}")
    return rc


def py(script, *args):
    return [sys.executable, "-I", f"{SRC}/{script}", *args]


# ----------------------------------------------------------------------------- shared prelude
def prelude():
    if not LOCAL:
        # fail fast if no GPU was attached (before downloading anything)
        run("nvidia-smi", ["nvidia-smi", "--query-gpu=name,memory.total,compute_cap", "--format=csv,noheader"], check=False)
        ok = subprocess.run([sys.executable, "-c", "import torch,sys; print(torch.__version__, torch.version.cuda, torch.cuda.is_available()); "
                             "sys.exit(0 if torch.cuda.is_available() else 3)"], env=ENV, capture_output=True, text=True)
        log("preinstalled torch:", ok.stdout.strip() or ok.stderr.strip()[-300:])
        if ok.returncode != 0:
            raise RuntimeError("no CUDA GPU available -- enable GPU in the kernel settings")

    shutil.rmtree(SRC, ignore_errors=True)
    os.makedirs(SRC)
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD_B64)), mode="r:gz") as tf:
        tf.extractall(SRC, filter="data")
    log("unpacked sources:", sorted(os.listdir(SRC)))

    if not LOCAL:
        # requirements (+ pins that worked on Kaggle's image; Kaggle's torchao 0.10 breaks peft's LoRA injection)
        run("pip-install", [sys.executable, "-m", "pip", "install", "-q", "-r", f"{SRC}/model-surgery/requirements.txt", *CONFIG["pip_extra"]])
        run("pip-uninstall-torchao", [sys.executable, "-m", "pip", "uninstall", "-y", "-q", "torchao"], check=False)
        if CONFIG.get("pip_nodeps"):  # e.g. flash-linear-attention, installed exactly as in an earlier working Qwen3.5 Kaggle test
            run("pip-install-nodeps", [sys.executable, "-m", "pip", "install", "-q", "--no-deps", *CONFIG["pip_nodeps"]], check=False)
        run("versions", [sys.executable, "-c", "import torch,transformers,peft,pyarrow; "
            "print('torch',torch.__version__,'transformers',transformers.__version__,'peft',peft.__version__,'pyarrow',pyarrow.__version__)"])
        run("fetch_data", py("model-surgery/fetch_data.py", "--out", DATA))
    run("textonly", py("model-surgery/textonly.py", BASE, TEXT))
    if CONFIG.get("selftest"):  # CPU-only mechanics check; non-fatal so a flaky check cannot cost the run, but it is logged
        run("selftest", ["timeout", "1200", *py(CONFIG.get("selftest_script", "llm2ncm/selftest.py"), TEXT)], check=False)


# ----------------------------------------------------------------------------- mode: pipeline
def sample_chat(gdir=None, out_md=None, env=None):
    """Ask the trained NCM the configured prompts; answers and stats go to chat_samples.md (non-fatal)."""
    gdir, out_md, env = gdir or f"{WORK}/generator", out_md or f"{OUT}/chat_samples.md", env or ENV
    parts = [f"# Chat samples from the trained NCM ({BASE})", "",
             f"Generated on Kaggle with `ncm_generate.py --refine {CONFIG['chat_refine']} --new {CONFIG['chat_new']}`.", ""]
    for prompt in CONFIG["chat_prompts"]:
        cmd = py("llm2ncm/ncm_generate.py", "--model", TEXT, "--generator", gdir, "--prompt", prompt,
                 "--refine", CONFIG["chat_refine"], "--new", CONFIG["chat_new"], "--device", DEVICE)
        r = subprocess.run([str(c) for c in cmd], cwd="/tmp", env=env, capture_output=True, text=True)
        stats = [l for l in r.stderr.splitlines() if l.startswith("[") and "forward passes" in l]
        parts += [f"## {prompt}", "", "```", r.stdout.strip() or f"(empty text after decoding, exit {r.returncode})", "```", "",
                  stats[-1] if stats else (r.stderr.strip()[-600:] if r.returncode else ""), ""]
        log(f"chat: {prompt!r} -> exit {r.returncode}")
    open(out_md, "w").write("\n".join(parts) + "\n")
    return parts


def run_pipeline():
    run("pipeline", py("llm2ncm/pipeline.py", "--model", TEXT, "--data", DATA, "--work", WORK, *CONFIG["pipeline_args"]))
    sample_chat()


def export_pipeline():
    for name in ("REPORT.md", "eval.json", "compressor.pt", "compressor.pt.json"):
        if os.path.exists(f"{WORK}/{name}"):
            shutil.copy(f"{WORK}/{name}", f"{OUT}/{name}")
    if os.path.isdir(f"{WORK}/generator"):
        shutil.copytree(f"{WORK}/generator", f"{OUT}/generator", dirs_exist_ok=True)


# ----------------------------------------------------------------------------- mode: variants
def stream(name, cmd, env, logfile):
    """Run cmd, copy every output line to logfile and, prefixed with [name], to the shared stdout (the live Logs tab)."""
    with open(logfile, "a") as f:
        p = subprocess.Popen([str(c) for c in cmd], cwd=ROOT if LOCAL else "/tmp", env=env, stdout=subprocess.PIPE,
                             stderr=subprocess.STDOUT, text=True, bufsize=1, errors="replace")
        for line in p.stdout:
            f.write(line)
            with _lock:
                sys.stdout.write(f"[{name}] {line}")
                sys.stdout.flush()
        return p.wait()


def snapshot(wd, od):
    """Copy the small artefacts (compressor, generator checkpoint, reports) out of /tmp into the output folder, so that a
    stop, a crash or a platform time-out still leaves a usable model behind. Best effort: a half-written checkpoint is
    simply overwritten by the next snapshot."""
    for fn in ("REPORT.md", "eval.json", "compressor.pt", "compressor.pt.json"):
        try:
            if os.path.exists(f"{wd}/{fn}"):
                shutil.copy(f"{wd}/{fn}", f"{od}/{fn}")
        except OSError:
            pass
    for sub in ("generator", "generator_best"):
        try:
            if os.path.isdir(f"{wd}/{sub}"):
                shutil.copytree(f"{wd}/{sub}", f"{od}/{sub}", dirs_exist_ok=True)
        except OSError:
            pass


def run_variant(v, gpu):
    """One full pipeline.py run on its own GPU; output lines are prefixed [name]. The variant either builds its own data
    (v["data_args"], e.g. a different block size) or takes a copy of the shared data."""
    name = v["name"]
    wd, od = f"{WORK}/{name}", f"{OUT}/{name}"
    os.makedirs(wd, exist_ok=True)
    os.makedirs(od, exist_ok=True)
    env = dict(ENV)
    if gpu is not None:
        env["CUDA_VISIBLE_DEVICES"] = str(gpu)
    if v.get("data_args"):
        t = time.time()
        cmd = py("llm2ncm/build_data.py", "--model", TEXT, "--data", DATA, "--out", f"{wd}/data.pt",
                 "--batch", 16 if LOCAL else 256, "--threads", 2, "--device", DEVICE, *v["data_args"])
        log(f"=== variant {name}: building its own data on gpu {gpu}")
        rc = stream(name, cmd, env, f"{od}/build_data.log")
        stages[f"build_data:{name}"] = {"exit": rc, "seconds": round(time.time() - t)}
        if rc != 0:
            return name, rc
    else:
        shutil.copy(f"{WORK}/shared/data.pt", f"{wd}/data.pt")
    extra = []
    if CONFIG.get("budget_hours"):  # generator training must end early enough for the evaluation to fit in the budget
        deadline = T0 + CONFIG["budget_hours"] * 3600 - CONFIG.get("eval_reserve_min", 25) * 60
        extra = ["--gen-deadline", f"{deadline:.0f}"]
    cmd = py("llm2ncm/pipeline.py", "--model", TEXT, "--data", DATA, "--work", wd, *CONFIG.get("data_args", []),
             *v.get("data_args", []), *CONFIG["common_args"], *v["args"], *extra)
    log(f"=== variant {name} on gpu {gpu}: {' '.join(map(str, cmd))}")
    t = time.time()
    stop = threading.Event()

    def periodic():
        while not stop.wait(CONFIG.get("ckpt_every_min", 30) * 60):
            snapshot(wd, od)
            log(f"variant {name}: checkpoint copied to the output folder")

    threading.Thread(target=periodic, daemon=True).start()
    rc = stream(name, cmd, env, f"{od}/pipeline.log")
    stop.set()
    stages[f"pipeline:{name}"] = {"exit": rc, "seconds": round(time.time() - t)}
    log(f"=== variant {name}: exit {rc} after {time.time() - t:.0f}s")
    if rc == 0:
        sample_chat(f"{wd}/generator", f"{od}/chat_samples.md", env)
    snapshot(wd, od)
    return name, rc


def write_compare(done):
    """COMPARE.md: every variant's quality table and chat answers side by side, plus the reference run (if configured)."""
    lines = [f"# {CONFIG['name']}: variants compared", ""]
    if CONFIG.get("reference"):
        lines += ["Reference (earlier run): " + CONFIG["reference"], ""]
    for name, rc in done:
        v = next(x for x in CONFIG["variants"] if x["name"] == name)
        lines += [f"## {name}: {v.get('note', '')}", "", f"`{' '.join(v['args'])}` (exit {rc})", ""]
        ev = f"{OUT}/{name}/eval.json"
        if os.path.exists(ev):
            lines += [json.load(open(ev))["table"], ""]
        md = f"{OUT}/{name}/chat_samples.md"
        if os.path.exists(md):
            lines += [l for l in open(md).read().splitlines() if not l.startswith("# Chat samples")] + [""]
    open(f"{OUT}/COMPARE.md", "w").write("\n".join(lines) + "\n")


def run_variants():
    vs = CONFIG["variants"]
    all_data_args = [*CONFIG.get("data_args", []), *[x for v in vs for x in v.get("data_args", [])]]
    if "--prompt-frac" in all_data_args:
        run("fetch_prompts", py("llm2ncm/fetch_prompts.py", "--out", DATA))
    os.makedirs(f"{WORK}/shared", exist_ok=True)
    shared = any(not v.get("data_args") for v in vs)  # only build the shared data if some variant uses it
    if shared:
        run("build_data", py("llm2ncm/build_data.py", "--model", TEXT, "--data", DATA, "--out", f"{WORK}/shared/data.pt",
                             "--batch", 16 if LOCAL else 256, "--threads", 4, "--device", DEVICE, *CONFIG["data_args"]))
    ngpu = 1
    if not LOCAL:
        out = subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout
        ngpu = max(1, sum(1 for l in out.splitlines() if l.startswith("GPU ")))
    assert len(vs) <= ngpu or LOCAL, f"{len(vs)} variants but only {ngpu} GPU(s)"
    with ThreadPoolExecutor(max_workers=len(vs)) as ex:
        futs = [ex.submit(run_variant, v, None if LOCAL else g) for g, v in enumerate(vs)]
        done = [f.result() for f in futs]
    if shared:
        os.remove(f"{WORK}/shared/data.pt")
    write_compare(done)
    if any(rc != 0 for _, rc in done):
        raise RuntimeError(f"variant(s) failed: {[n for n, rc in done if rc]}")


# ----------------------------------------------------------------------------- mode: jobs
def run_jobs():
    """One script per GPU, in parallel. Arguments may use {OUT}, {TEXT} and {DATA}."""
    jobs = CONFIG["jobs"]

    def go(job, gpu):
        env = dict(ENV)
        if gpu is not None:
            env["CUDA_VISIBLE_DEVICES"] = str(gpu)
        args = [str(x).replace("{OUT}", OUT).replace("{TEXT}", TEXT).replace("{DATA}", DATA).replace("{SRC}", SRC) for x in job["args"]]
        t = time.time()
        rc = stream(job["name"], py(job["script"], *args), env, f"{OUT}/{job['name']}.log")
        stages[f"job:{job['name']}"] = {"exit": rc, "seconds": round(time.time() - t)}
        return job["name"], rc

    with ThreadPoolExecutor(max_workers=len(jobs)) as ex:
        done = [f.result() for f in [ex.submit(go, j, None if LOCAL else g) for g, j in enumerate(jobs)]]
    if any(rc != 0 for _, rc in done):
        raise RuntimeError(f"job(s) failed: {[n for n, rc in done if rc]}")


# ----------------------------------------------------------------------------- mode: draft
def run_draft_head(h, gpu):
    """Train one draft head on its own GPU, then benchmark it (every dtype in CONFIG['bench_dtypes'])."""
    name = h["name"]
    wd, od = f"{WORK}/{name}", f"{OUT}/{name}"
    os.makedirs(wd, exist_ok=True)
    os.makedirs(od, exist_ok=True)
    env = dict(ENV)
    if gpu is not None:
        env["CUDA_VISIBLE_DEVICES"] = str(gpu)
    t = time.time()
    rc = stream(name, py("draft/train_draft.py", "--model", TEXT, "--data", f"{WORK}/draft_data.pt", "--out", f"{wd}/head.pt",
                         "--device", DEVICE, *CONFIG["train_args"], *h["args"]), env, f"{od}/train.log")
    stages[f"train:{name}"] = {"exit": rc, "seconds": round(time.time() - t)}
    if rc != 0 or not os.path.exists(f"{wd}/head.pt"):
        return name, rc or 1
    shutil.copy(f"{wd}/head.pt", f"{od}/head.pt")
    for dt in CONFIG.get("bench_dtypes", ["float32"]):
        t = time.time()
        rc = stream(f"{name}/{dt}", py("draft/bench_draft.py", "--model", TEXT, "--head", f"{wd}/head.pt", "--data", DATA,
                                       "--device", DEVICE, "--dtype", dt, "--out", f"{od}/bench_{dt}.json", *CONFIG["bench_args"]),
                    env, f"{od}/bench_{dt}.log")
        stages[f"bench:{name}:{dt}"] = {"exit": rc, "seconds": round(time.time() - t)}
        if rc != 0:
            return name, rc
    return name, 0


def run_draft():
    os.makedirs(WORK, exist_ok=True)
    run("fetch_prompts", py("llm2ncm/fetch_prompts.py", "--out", DATA))
    run("build_draft_data", py("draft/build_draft_data.py", "--model", TEXT, "--data", DATA, "--out", f"{WORK}/draft_data.pt",
                               "--device", DEVICE, *CONFIG["data_args"]))
    heads = CONFIG["heads"]
    with ThreadPoolExecutor(max_workers=len(heads)) as ex:
        done = [f.result() for f in [ex.submit(run_draft_head, h, None if LOCAL else g) for g, h in enumerate(heads)]]
    lines = [f"# {CONFIG['name']}: draft heads for {BASE}", "",
             "Every speculative output is checked token-for-token against plain greedy decoding ('exact match').", ""]
    for name, rc in done:
        h = next(x for x in heads if x["name"] == name)
        lines += [f"## {name}: {h.get('note', '')} (exit {rc})", ""]
        for dt in CONFIG.get("bench_dtypes", ["float32"]):
            bj = f"{OUT}/{name}/bench_{dt}.json"
            if os.path.exists(bj):
                b = json.load(open(bj))
                lines += [f"### {dt} ({b['prompts']} prompts, up to {b['max_new']} new tokens; head from step {b['head_step']})", "",
                          b["table"], ""]
    open(f"{OUT}/DRAFT_REPORT.md", "w").write("\n".join(lines) + "\n")
    if any(rc != 0 for _, rc in done):
        raise RuntimeError(f"draft head(s) failed: {[n for n, rc in done if rc]}")


# ----------------------------------------------------------------------------- mode: sweep
def last_dict(path, pattern):
    """The dict printed on the last log line matching `pattern` (e.g. '  val step 2000: {...}'), or None."""
    found = None
    try:
        for line in open(path, errors="replace"):
            if re.search(pattern, line):
                m = re.search(r"\{.*\}", line)
                if m:
                    found = m.group(0)
    except FileNotFoundError:
        return None
    if found is None:
        return None
    try:
        return json.loads(found.replace("'", '"').replace("True", "true").replace("False", "false"))
    except ValueError:
        return None


def run_job(job, gpu):
    name = job["name"]
    jd, od = f"{WORK}/{name}", f"{OUT}/sweep/{name}"
    os.makedirs(jd, exist_ok=True)
    os.makedirs(od, exist_ok=True)
    env = dict(ENV)
    if gpu is not None:
        env["CUDA_VISIBLE_DEVICES"] = str(gpu)
    t0 = time.time()
    res = {"name": name, "recipe": job["recipe"], "n": job["n"], "gpu": gpu, "note": job.get("note", ""), "seconds": {}}

    def step(tag, cmd):
        t = time.time()
        with open(f"{od}/{tag}.log", "w") as f:
            rc = subprocess.run([str(c) for c in cmd], cwd="/tmp", env=env, stdout=f, stderr=subprocess.STDOUT).returncode
        res["seconds"][tag] = round(time.time() - t)
        if rc != 0:
            raise RuntimeError(f"{name}/{tag} exited {rc} (see sweep/{name}/{tag}.log)")

    log(f"job {name}: start on gpu {gpu}")
    try:
        step("subset", py("llm2ncm/subset_data.py", "--data", f"{RECIPES}/{job['recipe']}.pt", "--out", f"{jd}/data.pt", "--n", job["n"]))
        step("compressor", py("llm2ncm/train_compressor.py", "--model", TEXT, "--data", f"{jd}/data.pt", "--out", f"{jd}/compressor.pt",
                              "--device", DEVICE, "--threads", 2, *job.get("comp", [])))
        step("generator", py("llm2ncm/train_generator.py", "--model", TEXT, "--data", f"{jd}/data.pt", "--compressor", f"{jd}/compressor.pt",
                             "--out", f"{jd}/generator", "--device", DEVICE, "--threads", 2, *job.get("gen", [])))
        step("quick_eval", py("llm2ncm/ncm_quick_eval.py", "--model", TEXT, "--generator", f"{jd}/generator", "--data", f"{jd}/data.pt",
                              "--out", f"{od}/quick_eval.json", "--device", DEVICE, "--threads", 2, *job.get("eval", [])))
        res["quick_eval"] = json.load(open(f"{od}/quick_eval.json"))
    except Exception as e:  # keep the sweep going; the error is recorded in the results
        res["error"] = str(e)
        log(f"job {name}: FAILED {e}")
    comp = f"{jd}/compressor.pt.json"
    if os.path.exists(comp):
        c = json.load(open(comp))
        res["compressor"] = {k: v for k, v in (c["history"][-1] if c["history"] else {}).items()}
        shutil.copy(comp, f"{od}/compressor.json")
    res["generator_val"] = last_dict(f"{od}/generator.log", r"^\s*val step \d+:")
    res["seconds"]["total"] = round(time.time() - t0)
    json.dump(res, open(f"{od}/result.json", "w"), indent=1)
    shutil.rmtree(jd, ignore_errors=True)  # data.pt / checkpoints are large and not exported
    log(f"job {name}: done in {res['seconds']['total']}s" + (" (with error)" if "error" in res else ""))
    return res


def fmt(x, nd=3):
    return "-" if x is None else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))


def write_results(results):
    rows = ["| job | n | note | comp acc (1 lvl / 2 lvl) | gen val L1 / L2 / tok | agree | oracle agree | judge bits (ref) | distinct-2 (ref) | real agree | min |",
            "|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in results:
        c, g, q = r.get("compressor") or {}, r.get("generator_val") or {}, r.get("quick_eval") or {}
        d, rl = q.get("distilled") or {}, q.get("real") or {}
        rows.append(f"| {r['name']} | {r['n']} | {r['note']} | {fmt(c.get('levels_1_token_acc'))} / {fmt(c.get('levels_2_token_acc'))} | "
                    f"{fmt(g.get('level1'), 2)} / {fmt(g.get('level2'), 2)} / {fmt(g.get('tokens'), 2)} | {fmt(d.get('agree'))} | "
                    f"{fmt(d.get('oracle_agree'))} | {fmt(d.get('judge_bits'), 2)} ({fmt(d.get('ref_bits'), 2)}) | "
                    f"{fmt(q.get('distinct2'))} ({fmt(q.get('ref_distinct2'))}) | {fmt(rl.get('agree'))} | "
                    f"{round(r['seconds'].get('total', 0) / 60)}{' ERR' if 'error' in r else ''} |")
    open(f"{OUT}/RESULTS.md", "w").write(
        f"# Sweep: {CONFIG['name']}\n\n`agree` = share of tokens equal to the original LLM's greedy block on held-out distilled windows "
        f"(higher is better); `judge bits` = the original LLM's bits/token on the NCM's block (lower is better, `ref` is the "
        f"floor); `oracle agree` = same as `agree` but the generator is given the true codes.\n\n" + "\n".join(rows) + "\n")
    json.dump(results, open(f"{OUT}/results.json", "w"), indent=1)
    log("RESULTS\n" + "\n".join(rows))


def run_sweep():
    os.makedirs(RECIPES, exist_ok=True)
    for name, r in CONFIG["recipes"].items():
        run(f"build_data:{name}", py("llm2ncm/build_data.py", "--model", TEXT, "--data", DATA, "--out", f"{RECIPES}/{name}.pt", "--n", r["n"],
                                    "--batch", 16 if LOCAL else 256, "--threads", 4, "--device", DEVICE, *r.get("args", [])))
    ngpu = 1
    if not LOCAL:
        out = subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout
        ngpu = max(1, sum(1 for l in out.splitlines() if l.startswith("GPU ")))
    log(f"sweep: {len(CONFIG['jobs'])} jobs on {ngpu} worker(s)")
    free = queue.Queue()
    for g in range(ngpu):
        free.put(None if LOCAL else g)

    def work(job):
        gpu = free.get()
        try:
            return run_job(job, gpu)
        finally:
            free.put(gpu)

    results = []
    with ThreadPoolExecutor(max_workers=ngpu) as ex:
        for fut in [ex.submit(work, j) for j in CONFIG["jobs"]]:
            results.append(fut.result())
            write_results(results)  # partial results survive a later crash/timeout


def export_sweep():
    pass  # everything is already written under OUT by run_job / write_results


# ----------------------------------------------------------------------------- driver
def export():
    {"sweep": export_sweep, "variants": lambda: None, "draft": lambda: None, "jobs": lambda: None}.get(CONFIG["mode"], export_pipeline)()
    json.dump({"config": CONFIG, "stages": stages, "total_seconds": round(time.time() - T0)},
              open(f"{OUT}/summary.json", "w"), indent=2)
    for root, _, files in os.walk(OUT):
        for f in sorted(files):
            p = os.path.join(root, f)
            log(f"output {os.path.relpath(p, OUT)}  {os.path.getsize(p) / 1e6:.2f} MB")


def main():
    log("Kaggle llm2ncm runner:", CONFIG["name"], f"(mode {CONFIG['mode']}{', LOCAL' if LOCAL else ''})")
    prelude()
    missing = [p for p in CONFIG.get("require", []) if not os.path.exists(p)]
    if missing:  # fail now, not after the two-hour data build
        raise SystemExit(f"missing inputs: {missing}")
    {"sweep": run_sweep, "variants": run_variants, "draft": run_draft, "jobs": run_jobs}.get(CONFIG["mode"], run_pipeline)()


if __name__ == "__main__":
    rc = 0
    try:
        main()
    except BaseException:
        rc = 1
        tb = traceback.format_exc()
        log("FAILED:\n" + tb)
        open(f"{OUT}/FAILED.txt", "w").write(tb)
    finally:
        try:
            export()
        except Exception:
            log("export failed:\n" + traceback.format_exc())
    sys.exit(rc)
